CREATE TABLE public.lawl_characters(user_id uuid NOT NULL,slot integer NOT NULL CHECK(slot BETWEEN 1 AND 5),data jsonb NOT NULL DEFAULT '{}'::jsonb,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,slot));
GRANT SELECT ON public.lawl_characters TO authenticated;
GRANT ALL ON public.lawl_characters TO service_role;
ALTER TABLE public.lawl_characters ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read own characters" ON public.lawl_characters FOR SELECT TO authenticated USING(auth.uid()=user_id);
ALTER TABLE public.game_saves ADD COLUMN character_slot integer NOT NULL DEFAULT 1 CHECK(character_slot BETWEEN 1 AND 5);
INSERT INTO public.lawl_characters(user_id,slot,data,updated_at) SELECT user_id,1,data,updated_at FROM public.game_saves WHERE coalesce(data->>'name','')<>'';
REVOKE INSERT,UPDATE,DELETE ON public.game_saves FROM authenticated;
CREATE FUNCTION public.lawl_mirror_character() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF coalesce(NEW.data->>'name','')<>'' THEN INSERT INTO public.lawl_characters(user_id,slot,data,updated_at) VALUES(NEW.user_id,NEW.character_slot,NEW.data,NEW.updated_at) ON CONFLICT(user_id,slot) DO UPDATE SET data=EXCLUDED.data,updated_at=EXCLUDED.updated_at; END IF; RETURN NEW; END $$;
CREATE TRIGGER lawl_mirror_character AFTER INSERT OR UPDATE ON public.game_saves FOR EACH ROW EXECUTE FUNCTION public.lawl_mirror_character();
CREATE OR REPLACE FUNCTION public.lawl_guard_gm_gems_save() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE delta bigint; cursor_id bigint; BEGIN IF TG_OP='UPDATE' AND OLD.character_slot=NEW.character_slot THEN cursor_id := coalesce((OLD.data->>'gmGemCursor')::bigint,0); IF coalesce((NEW.data->>'gmGemCursor')::bigint,0) < cursor_id THEN SELECT coalesce(sum((payload->>'amount')::bigint),0) INTO delta FROM public.lawl_gm_events WHERE action='gems' AND payload->>'target'=NEW.user_id::text AND id>coalesce((NEW.data->>'gmGemCursor')::bigint,0) AND id<=cursor_id; NEW.data := jsonb_set(jsonb_set(NEW.data,'{gems}',to_jsonb(coalesce((NEW.data->>'gems')::bigint,0)+delta)),'{gmGemCursor}',to_jsonb(cursor_id)); END IF; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.lawl_character_action(p_action text,p_slot integer,p_data jsonb DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); saved jsonb; active_slot integer; BEGIN
IF uid IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF;
IF p_slot IS NULL OR p_slot NOT BETWEEN 1 AND 5 THEN RAISE EXCEPTION 'Limite de 5 personagens por e-mail.'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(uid::text,0));
IF EXISTS(SELECT 1 FROM public.lawl_moderation WHERE user_id=uid AND suspended_until>now()) THEN RAISE EXCEPTION 'Account suspended'; END IF;
SELECT character_slot INTO active_slot FROM public.game_saves WHERE user_id=uid;
SELECT data INTO saved FROM public.lawl_characters WHERE user_id=uid AND slot=p_slot;
IF p_action IN ('select','create','delete') AND EXISTS(SELECT 1 FROM public.lawl_trades WHERE (user_a=uid::text OR user_b=uid::text) AND (status='pending' OR (user_a=uid::text AND NOT a_ack) OR (user_b=uid::text AND NOT b_ack))) THEN RAISE EXCEPTION 'Conclua ou cancele suas trocas antes de mudar de personagem.'; END IF;
IF p_action='select' THEN IF saved IS NULL THEN RAISE EXCEPTION 'Personagem não encontrado.'; END IF;
ELSIF p_action='create' THEN IF saved IS NOT NULL THEN RAISE EXCEPTION 'Este espaço já tem um personagem.'; END IF; IF (SELECT count(*) FROM public.lawl_characters WHERE user_id=uid)>=5 THEN RAISE EXCEPTION 'Limite de 5 personagens por e-mail.'; END IF; saved:=p_data;
ELSIF p_action='save' THEN IF saved IS NULL OR active_slot IS DISTINCT FROM p_slot THEN RAISE EXCEPTION 'Personagem alterado em outra sessão. Reabra seus personagens.'; END IF; saved:=p_data;
ELSIF p_action='delete' THEN DELETE FROM public.lawl_characters WHERE user_id=uid AND slot=p_slot; IF active_slot=p_slot THEN DELETE FROM public.game_saves WHERE user_id=uid; END IF; RETURN '{}'::jsonb;
ELSE RAISE EXCEPTION 'Ação inválida.'; END IF;
IF saved IS NULL OR jsonb_typeof(saved)<>'object' OR length(trim(coalesce(saved->>'name','')))=0 OR length(saved->>'name')>14 OR coalesce(saved->>'voc','') NOT IN ('knight','paladin','sorcerer','druid') THEN RAISE EXCEPTION 'Personagem inválido.'; END IF;
INSERT INTO public.game_saves(user_id,character_slot,data,updated_at) VALUES(uid,p_slot,saved,now()) ON CONFLICT(user_id) DO UPDATE SET character_slot=EXCLUDED.character_slot,data=EXCLUDED.data,updated_at=EXCLUDED.updated_at;
SELECT data INTO saved FROM public.game_saves WHERE user_id=uid; RETURN saved; END $$;
REVOKE ALL ON FUNCTION public.lawl_character_action(text,integer,jsonb),public.lawl_mirror_character() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.lawl_character_action(text,integer,jsonb) TO authenticated;